-- PR-T1 data step (planner's reading 4, approved 2026-11-20): today's card prices stay identical.
-- Idempotent: a seed counts as done when its promotion (`created_by` null) exists, so a second run
-- matches nothing. Plan `updated_at` is not touched and no `plan_audit_logs` row is written (a data
-- migration, not an admin edit; like 0022). Ids are UUIDv7 built like 0023 (Postgres 17).

-- 1. Yearly per-month price becomes a list price: + (list − offer), the value of the plan's
--    "Launch offer" (step 2), so list − offer still shows today's yearly price (৳449 → ৳949,
--    ৳1,349 → ৳2,349, ৳3,599 → ৳5,599). Same plans as step 2, before it runs.
UPDATE "plans" AS p
SET "yearly_monthly_price_bdt" = p."yearly_monthly_price_bdt" + (p."monthly_price_bdt" - p."offer_price_bdt")
WHERE p."offer_price_bdt" IS NOT NULL
	AND p."offer_price_bdt" < p."monthly_price_bdt"
	AND p."yearly_monthly_price_bdt" IS NOT NULL
	AND NOT EXISTS (
		SELECT 1 FROM "promotions" pr
		JOIN "promotion_plans" pp ON pp."promotion_id" = pr."id"
		WHERE pp."plan_id" = p."id" AND pr."kind" = 'DISCOUNT' AND pr."name" = 'Launch offer' AND pr."created_by" IS NULL
	);
--> statement-breakpoint

-- 2. One "Launch offer" DISCOUNT per plan with an offer below its list price: FLAT, each month's
--    price, that plan only, forever, no end date, value = list − offer (৳500 / ৳1,000 / ৳2,000).
WITH "src" AS (
	SELECT
		encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid()) PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3) FROM 1 FOR 6), 52, 1), 53, 1), 'hex')::uuid AS "promotion_id",
		p."id" AS "plan_id",
		p."monthly_price_bdt" - p."offer_price_bdt" AS "value"
	FROM "plans" p
	WHERE p."offer_price_bdt" IS NOT NULL
		AND p."offer_price_bdt" < p."monthly_price_bdt"
		AND NOT EXISTS (
			SELECT 1 FROM "promotions" pr
			JOIN "promotion_plans" pp ON pp."promotion_id" = pr."id"
			WHERE pp."plan_id" = p."id" AND pr."kind" = 'DISCOUNT' AND pr."name" = 'Launch offer' AND pr."created_by" IS NULL
		)
), "inserted" AS (
	INSERT INTO "promotions" ("id", "kind", "name", "discount_type", "discount_value", "discount_scope")
	SELECT "promotion_id", 'DISCOUNT', 'Launch offer', 'FLAT', "value", 'PER_MONTH' FROM "src"
)
INSERT INTO "promotion_plans" ("promotion_id", "plan_id")
SELECT "promotion_id", "plan_id" FROM "src";
--> statement-breakpoint

-- 3. "Starter N-day trial" from Starter's trial columns (seed 7 days, 300 comments), Starter only,
--    no end date. Skipped when Starter has no trial.
WITH "src" AS (
	SELECT
		encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid()) PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3) FROM 1 FOR 6), 52, 1), 53, 1), 'hex')::uuid AS "promotion_id",
		p."id" AS "plan_id",
		p."trial_days",
		p."trial_comment_limit"
	FROM "plans" p
	WHERE p."slug" = 'starter'
		AND p."trial_days" IS NOT NULL
		AND NOT EXISTS (
			SELECT 1 FROM "promotions" pr
			JOIN "promotion_plans" pp ON pp."promotion_id" = pr."id"
			WHERE pp."plan_id" = p."id" AND pr."kind" = 'TRIAL' AND pr."created_by" IS NULL
		)
), "inserted" AS (
	INSERT INTO "promotions" ("id", "kind", "name", "trial_days", "trial_comment_limit")
	SELECT "promotion_id", 'TRIAL', 'Starter ' || "trial_days" || '-day trial', "trial_days", "trial_comment_limit" FROM "src"
)
INSERT INTO "promotion_plans" ("promotion_id", "plan_id")
SELECT "promotion_id", "plan_id" FROM "src";
